package byx.demo;
import javafx.application.*;import javafx.scene.*;import javafx.scene.control.*;import javafx.scene.layout.*;import javafx.geometry.*;import javafx.stage.*;import java.util.*;
import panel.authview.AuthLayout;import panel.design.*;import panel.motion.*;import panel.shell.*;import panel.nav.Navigator;import panel.tradeview.*;import panel.ui.View;import panel.accountview.*;
/** Only local UI and deterministic fixtures are composed. There is no authority/backend object. */
public final class DemoApp extends Application {
 public static final Set<String> ROUTES=Set.of("t-home","t-desk","t-markets","t-portfolio","t-positions","t-orders","t-history","t-settings","h-faq","h-help","h-about","h-terms","h-privacy","h-shortcuts","sys-status");
 final DemoAuthProvider auth=new DemoAuthProvider();final MotionService motion=new MotionService();StackPane root=new StackPane();Scene scene;Stage stage;AuthLayout login;ByxField identifier,password;ByxShell shell;ShellRouter router;View current;ShellPalette palette;String symbol="ETHUSDT";
 private final Preferences preferences=new Preferences();
 @Override public void start(Stage s){stage=s;ByxFonts.load();root.getStyleClass().add("comfortable");scene=new Scene(root,1440,900);ByxTheme.apply(scene);stage.setTitle("BYX-MVP DEMO — DADOS SIMULADOS");stage.setScene(scene);stage.setMinWidth(1100);stage.setMinHeight(720);stage.setOnCloseRequest(e->cleanup());showLogin(null);stage.show();motion.reference.bind(root);}
 void showLogin(String error){cleanupViews();auth.logout();identifier=ByxField.text("Email or username");password=ByxField.password("Password");identifier.input().setId("demo-user");password.input().setId("demo-password");identifier.input().setPromptText("teste-byx");password.input().setPromptText("Enter your password");ByxButton submit=new ByxButton("Sign in",ByxButton.Variant.PRIMARY,motion).wide();submit.setId("demo-login");submit.setDefaultButton(true);submit.setOnAction(e->{char[] secret=password.input().getText().toCharArray();boolean ok=auth.login(identifier.input().getText(),secret);password.input().clear();if(ok)workspace();else showLogin("Login ou senha incorretos. Use as credenciais públicas da DEMO.");});login=new AuthLayout(motion,"DEMO OFFLINE",this::publicHelp);Label title=new Label("Sign in");title.getStyleClass().add("byx-auth-title");Label subtitle=new Label("Access the BYX-MVP terminal.");subtitle.getStyleClass().add("byx-auth-sub");Label note=new Label("DEMO: teste-byx / byx123123\nDADOS SIMULADOS · SEM OPERAÇÕES REAIS");note.setWrapText(true);note.getStyleClass().add("byx-auth-sub");List<Node> form=new ArrayList<>(List.of(new VBox(4,title,subtitle)));if(error!=null)form.add(new ByxBanner(ByxBanner.Kind.ERROR,"Sign-in failed",error));form.addAll(List.of(identifier,password,submit,note));login.show("Sign in",form);root.getChildren().setAll(login);Platform.runLater(()->identifier.input().requestFocus());}
 boolean permitted(String route){return auth.session()!=null&&ROUTES.contains(route);}
 void workspace(){login.brand().dispose();router=new ShellRouter(new Navigator(),(target,ticket)->permitted(target)?ShellRouter.Decision.ALLOW:ShellRouter.Decision.DENY,this::display);shell=new ByxShell(router,motion,new LegacyHost());shell.setAvailable(this::permitted);shell.switcher().setVisible(ShellContext.RESEARCH,false);shell.switcher().setVisible(ShellContext.BYX,false);shell.showV2(true);shell.topBar().setUser("DEMO_USER / USER");shell.topBar().setMockData(true);shell.topBar().setAdminSession(false);shell.topBar().avatar().setOnAction(e->showLogin(null));shell.topBar().avatar().setTooltip(new Tooltip("Logout DEMO"));Button logout=new Button("Logout");logout.setId("demo-logout");logout.setOnAction(e->showLogin(null));Label badge=new Label("USER / DEMO · DADOS SIMULADOS · SEM OPERAÇÕES REAIS · OFFLINE");HBox bar=new HBox(14,badge,logout);bar.setPadding(new Insets(8,16,8,16));bar.setAlignment(Pos.CENTER_LEFT);shell.setGlobalBar(bar);bar.setOpacity(1);badge.setStyle("-fx-text-fill: #8fa2ff;");palette=new ShellPalette(shell.overlay(),router::request,()->ROUTES.stream().sorted().map(r->ShellPalette.Entry.nav(r,r,"DEMO offline")).toList());shell.setOnOpenSearch(palette::open);root.getChildren().setAll(shell);router.request("t-desk");}
 void display(String route){if(!permitted(route))throw new IllegalStateException("DEMO route denied");if(current!=null)current.dispose();if(route.equals("t-desk"))current=new TradingDesk(motion,()->DemoFixtures.market(symbol),DemoFixtures.CLOCK);else if(route.equals("t-markets")||route.equals("t-portfolio"))current=new MarketsPage(()->DemoFixtures.market(symbol),DemoFixtures.CLOCK,router::request);else if(route.equals("t-settings"))current=new SettingsScreen(motion,preferences,router::request,()->shell.overlay());else current=simple(route);current.onSnapshot(new panel.model.Snapshot());current.onShow();VBox content=new VBox(10);if(route.startsWith("t-")&&!route.equals("t-settings")){ComboBox<String> watch=new ComboBox<>();watch.getItems().addAll("ETHUSDT","BTCUSDT");watch.setValue(symbol);watch.setId("demo-watchlist");watch.valueProperty().addListener((o,a,b)->{if(b!=null&&!b.equals(symbol)){symbol=b;display(route);}});HBox watchlist=new HBox(10,panel.tradeview.Fx.label("Watchlist — DEMO", "byx-muted"),watch);watchlist.setPadding(new Insets(8,20,0,20));content.getChildren().add(watchlist);}Node node=current.node();VBox.setVgrow(node,Priority.ALWAYS);content.getChildren().add(node);shell.v2Content().getChildren().setAll(content);}
 View simple(String route){VBox page=new VBox(18);page.setPadding(new Insets(28));Label title=new Label(route);title.getStyleClass().add("byx-auth-title");page.getChildren().addAll(title,new Label("DEMO · DADOS SIMULADOS · SEM OPERAÇÕES REAIS"));if(route.equals("t-home")){for(String r:List.of("t-desk","t-markets","t-positions","t-orders","t-history","t-settings")){Button b=new Button(r);b.setOnAction(e->router.request(r));page.getChildren().add(b);}}else if(route.equals("t-orders"))page.getChildren().add(new Label("Ordens reais e envio de ordens: indisponíveis nesta composição."));else if(route.equals("t-positions")||route.equals("t-history")){for(String[] row:route.equals("t-positions")?DemoFixtures.market(symbol).positionRows:DemoFixtures.market(symbol).tradeRows)page.getChildren().add(new Label(String.join("  |  ",row)));}else page.getChildren().add(new Label("Explore Trading Desk, Markets & Portfolio e Settings. Login público: teste-byx / byx123123.\nFeedback: abra GitHub Issues em ChamberUS/DEV. Não envie senhas ou dados privados.\nService, pesquisa, ordens, carteiras e transações reais não fazem parte desta DEMO."));return new View(){public Node node(){return page;}public void onSnapshot(panel.model.Snapshot ignored){}};}
 void publicHelp(String ignored){Alert a=new Alert(Alert.AlertType.INFORMATION,"BYX-MVP DEMO offline. Credenciais públicas: teste-byx / byx123123. Sem operações reais. Feedback: GitHub Issues ChamberUS/DEV.",ButtonType.OK);a.initOwner(stage);a.showAndWait();}
 void cleanupViews(){if(current!=null){current.dispose();current=null;}if(palette!=null){palette.close();palette=null;}if(shell!=null){shell.dispose();shell=null;}if(login!=null){login.brand().dispose();login=null;}}
 void cleanup(){cleanupViews();auth.logout();motion.setActive(false);} @Override public void stop(){cleanup();}
 final class Preferences implements AccountData{Prefs value=new Prefs("FULL","COMFORTABLE",true,"TRADING",false);public Prefs prefs(){return value;}public boolean adminSession(){return false;}public boolean preferencesEditable(){return true;}public String effectiveMotion(){return motion.preference.get().name();}public void savePrefs(Prefs p){MotionPreference m=MotionPreference.valueOf(p.motion());if(!Set.of("COMPACT","COMFORTABLE").contains(p.density())||!p.primaryWorkspace().equals("TRADING"))throw new IllegalArgumentException("DEMO display preferences only");value=p;motion.preference.set(m);motion.animatedIcons.set(p.animatedIcons());root.getStyleClass().remove("comfortable");if(p.density().equals("COMFORTABLE"))root.getStyleClass().add("comfortable");if(shell!=null)shell.content().setComfortable(p.density().equals("COMFORTABLE"));}}
}